#ifndef DIAG_H_
#define DIAG_H_

// TouchIDDiag runs the native availability checks and writes each result to
// its corresponding output parameter. It returns zero when the checks ran.
int TouchIDDiag(int *hasSignatureOut, int *hasEntitlementsOut,
                int *passedLAPolicyTestOut, int *passedSecureEnclaveTestOut);

#endif // DIAG_H_
}

// CredentialInfo holds information about a Secure Enclave credential.
type CredentialInfo struct {
	UserHandle   []byte
	CredentialID string
	RPID         string
	User         string
	PublicKey    *ecdsa.PublicKey

	// publicKeyRaw is used internally to return public key data from native
	// register requests.
	publicKeyRaw []byte
}

// DiagResult contains the results of the Touch ID availability checks.
type DiagResult struct {
	HasCompileSupport       bool
	HasSignature            bool
	HasEntitlements         bool
	PassedLAPolicyTest      bool
	PassedSecureEnclaveTest bool
	IsAvailable             bool
}

// Diag runs the Touch ID availability checks and returns their individual
// results along with the aggregate availability status.
func Diag() (*DiagResult, error) {
	return nativeDiag()
}

// IsAvailable returns true if Touch ID is available in the system.
// Presently, IsAvailable is hidden behind a somewhat cheap check, so it may be
// prone to false positives (for example, a binary compiled with Touch ID
// support but not properly signed/notarized).
// In case of false positives, other Touch IDs should fail gracefully.
func IsAvailable() bool {
	return native.IsAvailable()
}

// Register creates a new Secure Enclave-backed biometric credential.
func Register(origin string, cc *wanlib.CredentialCreation) (*wanlib.CredentialCreationResponse, error) {
	if !native.IsAvailable() {
		return nil, ErrNotAvailable
	}

	// Ignored cc fields:
	// - Timeout - we don't control touch ID timeouts (also the server is free to
	//   enforce it)
	// - CredentialExcludeList - we always allow re-registering (for various
	//   reasons).
	l := label[len(rpIDUserMarker):]

	idx := strings.Index(l, labelSeparator)
	if idx == -1 {
		return nil, trace.BadParameter("label separator not found: %q", label)
	}

	return &parsedLabel{
		rpID: l[0:idx],
		user: l[idx+1:],
	}, nil
}

var native nativeTID = &touchIDImpl{}

type touchIDImpl struct{}

func (touchIDImpl) IsAvailable() bool {
	diag, err := nativeDiag()
	return err == nil && diag.IsAvailable
}

func nativeDiag() (*DiagResult, error) {
	var hasSignature, hasEntitlements, passedLAPolicyTest, passedSecureEnclaveTest C.int
	if C.TouchIDDiag(
		&hasSignature,
		&hasEntitlements,
		&passedLAPolicyTest,
		&passedSecureEnclaveTest,
	) != 0 {
		return nil, errors.New("failed to run Touch ID diagnostics")
	}

	result := &DiagResult{
		HasCompileSupport:       true,
		HasSignature:            hasSignature != 0,
		HasEntitlements:         hasEntitlements != 0,
		PassedLAPolicyTest:      passedLAPolicyTest != 0,
		PassedSecureEnclaveTest: passedSecureEnclaveTest != 0,
	}
	result.IsAvailable = result.HasCompileSupport && result.HasSignature &&
		result.HasEntitlements && result.PassedLAPolicyTest && result.PassedSecureEnclaveTest
	return result, nil
}

func (touchIDImpl) Register(rpID, user string, userHandle []byte) (*CredentialInfo, error) {
	credentialID := uuid.NewString()
	userHandleB64 := base64.RawURLEncoding.EncodeToString(userHandle)

	var req C.CredentialInfo
	req.label = C.CString(makeLabel(rpID, user))
	req.app_label = C.CString(credentialID)
	req.app_tag = C.CString(userHandleB64)
	defer func() {
		C.free(unsafe.Pointer(req.label))
		C.free(unsafe.Pointer(req.app_label))
		C.free(unsafe.Pointer(req.app_tag))
	}()

	var errMsgC, pubKeyC *C.char
	defer func() {
